  "The Cooperative Admin Portal is the federation's central command system. Administrators use this portal to verify worker credentials, oversee automated geo-dispatching, monitor fair wage disbursements, detect financial anomalies, and forecast future labor demand using predictive AI models.": "The Cooperative Admin Portal is the federation's central command system. Administrators use this portal to verify worker credentials, oversee automated geo-dispatching, monitor fair wage disbursements, detect financial anomalies, and forecast future labor demand using predictive AI models.",
  "The SahakarConnect Household Portal gives you direct access to background-verified, skilled cooperative workers at fair, standardized hourly tariffs. Your payments are protected in secure escrow, and jobs only start when you share your 4-digit arrival OTP.": "The SahakarConnect Household Portal gives you direct access to background-verified, skilled cooperative workers at fair, standardized hourly tariffs. Your payments are protected in secure escrow, and jobs only start when you share your 4-digit arrival OTP.",
