  "helpOfficerAuditDesc": "ನಿಯಮಿತ ಹಣಕಾಸು ಲೆಕ್ಕಪರಿಶೋಧನೆ ಮತ್ತು ಕನಿಷ್ಠ ವೇತನ ನಿಯಮಗಳ ಪಾಲನೆ ಪರಿಶೀಲನೆ.",
  "helpOfficerAuditStep1": "ಎಲ್ಲಾ ವಹಿವಾಟುಗಳನ್ನು ಪರಿಶೀಲಿಸಿ 95% ವೇತನ ಪಾವತಿಯನ್ನು ದೃಢೀಕರಿಸಿ.",
  "helpOfficerAuditStep2": "ಕಲ್ಯಾಣ ನಿಧಿ ಕೊಡುಗೆಗಳು ಮತ್ತು ಅಪಘಾತ ವಿಮಾ ರಕ್ಷಣೆಯನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "helpOfficerAuditStep3": "कायदेशीर प्रमाणपत्रे जारी करा किंवा त्रुटींवर कारवाईचे आदेश द्या.",
  "helpOfficerAuditTitle": "ಕಾನೂನು ಮತ್ತು ಹಣಕಾಸು ಲೆಕ್ಕಪರಿಶೋಧನೆ",
  "helpOfficerBannerDesc": "ಸಹಕಾರಿ ಸಂಸ್ಥೆಗಳಿಗೆ ಕಾನೂನು ಸಮ್ಮತಿ, ದೂರು ಮಧ್ಯಸ್ಥಿಕೆ ಮತ್ತು ಕಾರ್ಮಿಕ ಕಲ್ಯಾಣ ತಪಾಸಣಾ ಪೋರ್ಟಲ್.",
  "helpOfficerCasesDesc": "ਕਾਮਿਆਂ ਅਤੇ ਗਾਹਕਾਂ ਵਿਚਕਾਰ ਵਿਵਾਦਾਂ ਦੀ ਸੁਣਵਾਈ ਅਤੇ ਨਿਆਂਇਕ ਫੈਸਲੇ।",
  "helpOfficerCasesTitle": "ਕੇਸ ਪ੍ਰਬੰਧਨ ਅਤੇ ਸੁਣਵਾਈ",
  "helpOfficerDashDesc": "ਸਹਿਕਾਰੀ ਫੈਡਰੇਸ਼ਨ ਦੇ ਉਜਰਤ ਆਡਿਟ ਅਤੇ ਲੇਬਰ ਕਾਨੂੰਨ ਪਾਲਣਾ ਦੀ ਰੀਅਲ-ਟਾਈਮ ਨਿਗਰਾਨੀ।",
  "helpOfficerDashTitle": "ਅਧਿਕਾਰੀ ਡੈਸ਼ਬੋਰਡ ਅਤੇ ਨਿਗਰਾਨੀ",
  "helpOfficerFaq1A": "Yes. Under the cooperative dispute framework, decisions recorded by registered Labor Department Officers are binding on cooperative escrow settlements and platform standings.",
  "helpOfficerFaq1Q": "Are rulings issued by the Labor Officer legally binding?",
  "helpOfficerFaq2A": "All evidence attachments (photos, chat logs, bills) and Geo-Dispatch timestamps are cryptographically anchored to prevent tampering.",
  "helpOfficerFaq2Q": "How does the system ensure evidence integrity?",
