  "workerFlowStep1Desc": "ಸಕ್ರಿಯ ಉದ್ಯೋಗಗಳ ವಿಭಾಗದಲ್ಲಿ ಸ್ಥಳ ಮತ್ತು ವೇತನ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ನಂತರ ಒಪ್ಪಿಕೊಳ್ಳಿ ಕ್ಲಿಕ್ ಮಾಡಿ.",
  "workerFlowStep1Title": "ಕೆಲಸವನ್ನು ಸ್ವೀಕರಿಸಿ ಮತ್ತು ಒಪ್ಪಿಕೊಳ್ಳಿ:",
  "workerFlowStep2Desc": "ಗ್ರಾಹಕರು ನಿಮ್ಮ ಆಗಮನದ ಸ್ಥಿತಿಯನ್ನು ನೋಡಲು \"ದಾರಿಯಲ್ಲಿದ್ದೇನೆ\" ಕ್ಲಿಕ್ ಮಾಡಿ.",
