  "workerFlowStep3Desc": "ಗ್ರಾಹಕರ ಮನೆಗೆ ತಲುಪಿದಾಗ, ಅವರ 4-ಅಂಕಿಯ ಕೋಡ್ ಅನ್ನು ಕೇಳಿ ಕೆಲಸವನ್ನು ಪ್ರಾರಂಭಿಸಿ.",
  "workerFlowStep3Title": "ಕೆಲಸ ಪ್ರಾರಂಭದ OTP ನಮೂದಿಸಿ:",
  "workerFlowStep4Desc": "ಕೆಲಸ ಮುಗಿದ ನಂತರ \"ಪೂರ್ಣಗೊಂಡಿದೆ\" ಎಂದು ಗುರುತಿಸಿ. ಶೂನ್ಯ ಕಮಿಷನ್‌ನೊಂದಿಗೆ ಸಂಪೂರ್ಣ ವೇತನ ತಕ್ಷಣವೇ ನಿಮ್ಮ ಖಾತೆಗೆ ಜಮೆಯಾಗುತ್ತದೆ.",
  "workerFlowStep4Title": "ಕೆಲಸ ಮುಗಿಸಿ ತಕ್ಷಣ ವೇತನ ಪಡೆಯಿರಿ:",
  "workerFlowStep5Desc": "ಉತ್ತಮ ರೇಟಿಂಗ್‌ಗಳನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಿ, ಅಕಾಡೆಮಿ ಪಾಠಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ ಮತ್ತು ಹೆಚ್ಚಿನ ವೇತನದ ಕೆಲಸಗಳನ್ನು ಪಡೆಯಿರಿ.",
  "workerFlowStep5Title": "ಕೌಶಲ್ಯ ಹೆಚ್ಚಿಸಿ ಮತ್ತು ಆದಾಯ ಹೆಚ್ಚಿಸಿಕೊಳ್ಳಿ:",
  "workerHowItWorksDesc": "ಸಹಕಾರ್ ಕನೆಕ್ಟ್ ವರ್ಕರ್ ಪೋರ್ಟಲ್ ಯಾವುದೇ ಮಧ್ಯವರ್ತಿಗಳಿಲ್ಲದೆ ನಿಮ್ಮನ್ನು ನೇರವಾಗಿ ಹತ್ತಿರದ ಗ್ರಾಹಕರೊಂದಿಗೆ ಸಂಪರ್ಕಿಸುತ್ತದೆ. ನೀವು ಕೆಲಸದ ವಿನಂತಿಗಳನ್ನು ಸ್ವೀಕರಿಸಬಹುದು, ಸುರಕ್ಷಿತ OTP ಯೊಂದಿಗೆ ಕೆಲಸವನ್ನು ಪ್ರಾರಂಭಿಸಬಹುದು, ತಕ್ಷಣವೇ ನಿಮ್ಮ ವೇತನವನ್ನು ಪಡೆಯಬಹುದು ಮತ್ತು ಸಹಕಾರಿ ಸಾಮಾಜಿಕ ಭದ್ರತಾ ಪ್ರಯೋಜನಗಳನ್ನು ಪಡೆಯಬಹುದು.",
